import{_ as e,o as n,c as o,aa as i}from"./chunks/framework.BAs_AphD.js";const t="/buildary-help-preview/media/cs/diary/m_popis_cisla.png",r="/buildary-help-preview/media/cs/diary/m_menudne.png",l="/buildary-help-preview/media/cs/diary/m_dz_menu.png",c=JSON.parse('{"title":"Denní záznamy v mobilu","description":"","frontmatter":{"title":"Denní záznamy v mobilu","wiki":"cs:diary:m_dailyentries"},"headers":[],"relativePath":"diary/m_dailyentries.md","filePath":"diary/m_dailyentries.md","lastUpdated":1794209661000}'),s={name:"diary/m_dailyentries.md"};function d(p,a,m,z,u,k){return n(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="denni-zaznamy-v-mobilu" tabindex="-1">Denní záznamy v mobilu <a class="header-anchor" href="#denni-zaznamy-v-mobilu" aria-label="Permalink to &quot;Denní záznamy v mobilu&quot;">​</a></h1><p>V mobilní aplikaci zapisujete denní záznamy přímo na stavbě: počasí, osoby, stroje, materiály, provedené práce i Další záznamy s fotkami. Tato stránka popisuje, jak se s nimi pracuje na telefonu. Co jednotlivé části deníku znamenají, najdete na stránce <a href="/buildary-help-preview/diary/dailyentries">Denní záznamy</a>.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/mobilni-aplikace-denik">Psát deník v mobilu</a> v Akademii.</p><h2 id="obrazovka-dennich-zaznamu" tabindex="-1">Obrazovka denních záznamů <a class="header-anchor" href="#obrazovka-dennich-zaznamu" aria-label="Permalink to &quot;Obrazovka denních záznamů&quot;">​</a></h2><figure class="shot" style="--w:260px;"><img src="'+t+'" alt="Obrazovka denních záznamů v mobilu s očíslovanými částmi" loading="lazy"></figure><ol><li><strong>Horní lišta</strong> – vlevo <a href="/buildary-help-preview/diary/m_project_list">menu aplikace</a>, dál název deníku, ikona poznámky ke dni a vpravo nabídka dne (tři tečky).</li><li><strong>Datum</strong> – šipkami přejdete o den zpět nebo vpřed. Klepnutím na datum otevřete kalendář a vyberete libovolný den. Barevný pruh pod datem ukazuje stav dne; co barvy znamenají, viz <a href="/buildary-help-preview/diary/dailyentries">Denní záznamy</a>.</li><li><strong>Lišta sekce</strong> – název sekce, ikona poznámky k sekci a lupa pro hledání v sekci. Sekce Provedené práce a Další záznamy poznámku nemají.</li><li><strong>Záznamy</strong> vybrané sekce.</li><li><strong>Sekce</strong> – mezi sekcemi přepínáte lištou dole nebo potažením prstu do strany. Sekce, které se do lišty nevejdou, najdete pod <strong>Více</strong>.</li></ol><h2 id="poznamka-ke-dni" tabindex="-1">Poznámka ke dni <a class="header-anchor" href="#poznamka-ke-dni" aria-label="Permalink to &quot;Poznámka ke dni&quot;">​</a></h2><p>Ke každému dni můžete přidat veřejnou nebo soukromou poznámku. Veřejnou vidí všichni, kdo mají do deníku přístup, soukromou jen vy. Poznámku vložíte i zobrazíte ikonou bubliny v horní liště. Prázdná bublina znamená, že poznámka zatím není, vyplněná bublina, že poznámka existuje.</p><h2 id="nabidka-dne" tabindex="-1">Nabídka dne <a class="header-anchor" href="#nabidka-dne" aria-label="Permalink to &quot;Nabídka dne&quot;">​</a></h2><p>Nabídku otevřete ikonou tří teček vpravo v horní liště. Ukazuje jen volby, které jdou ve stavu zobrazeného dne použít.</p><figure class="shot" style="--w:300px;"><img src="'+r+'" alt="Nabídka dne s volbami Stažení dne v PDF, Podepsat den, Kopírovat celý den, Uživatelské zamčení dne a Nepracovní den" loading="lazy"></figure><ul><li><strong>Stažení dne v PDF</strong> – stáhne Denní protokol zobrazeného dne.</li><li><strong>Podepsat den</strong> – podepíše a zamkne den. Pokud podepisujete v externí aplikaci, jsou tu místo toho volby <strong>Stažení k elektronickému podpisu</strong> a <strong>Nahrej elektronicky podepsaný soubor</strong>. Viz <a href="/buildary-help-preview/diary/m_signing">Podepisování v mobilu</a>.</li><li><strong>Kopírovat celý den</strong> – nejdřív v kalendáři vyberte den, ze kterého chcete kopírovat. Pak zvolte sekce a případně jen záznamy vybraného autora. Viz <a href="/buildary-help-preview/diary/copydailyentries">Kopírovat záznamy</a>.</li><li><strong>Uživatelské zamčení dne</strong> – zamkne den s aktuálním obsahem; záznamy pak nejde přidávat ani měnit. Zámek zrušíte volbou <strong>Zruš uživatelské zamčení dne</strong>.</li><li><strong>Nepracovní den</strong> – označí den jako nepracovní. Opačná volba <strong>Pracovní den</strong> ho vrátí.</li></ul><div class="danger custom-block"><p class="custom-block-title">Nepracovní den maže záznamy</p><p>Když den označíte jako nepracovní, smažou se všechny jeho záznamy.</p></div><h2 id="pridat-a-upravit-zaznam" tabindex="-1">Přidat a upravit záznam <a class="header-anchor" href="#pridat-a-upravit-zaznam" aria-label="Permalink to &quot;Přidat a upravit záznam&quot;">​</a></h2><ul><li><strong>Přidat</strong> – klepněte na tlačítko <strong>+</strong> vpravo dole a vyplňte formulář. Při psaní vám aplikace nabízí položky, které už v této sekci deníku jsou.</li><li><strong>Upravit</strong> – klepněte na záznam; otevře se k úpravě.</li><li><strong>Smazat více záznamů</strong> – podržte prst na záznamu. U záznamů se objeví zaškrtávací políčka; označte ty, které chcete smazat, a klepněte na ikonu koše v liště sekce.</li></ul><p>K sekcím Počasí, Osoby na staveništi, Mechanizmy a Materiály, výrobky a technologické dodávky můžete připsat poznámku ikonou bubliny v liště sekce. Co do jednotlivých sekcí patří, popisuje <a href="/buildary-help-preview/diary/dailyentriespersons">Počasí, osoby, stroje a materiály</a>.</p><h2 id="pocasi" tabindex="-1">Počasí <a class="header-anchor" href="#pocasi" aria-label="Permalink to &quot;Počasí&quot;">​</a></h2><p>Klepněte na ikonu obláčku a aplikace načte počasí z internetu. Stavba musí mít polohu v mapě – viz <a href="/buildary-help-preview/diary/projectsetup#umisteni">Založit stavbu – Umístění</a>. Nezáleží na tom, kdy počasí načítáte – aplikace použije naměřené hodnoty, nebo předpověď, podle toho, co je k dispozici.</p><p>Načtené hodnoty upravíte klepnutím na řádek. Všechny najednou smažete ikonou koše v liště sekce.</p><h2 id="provedene-prace-a-dalsi-zaznamy" tabindex="-1">Provedené práce a Další záznamy <a class="header-anchor" href="#provedene-prace-a-dalsi-zaznamy" aria-label="Permalink to &quot;Provedené práce a Další záznamy&quot;">​</a></h2><p>Ve formuláři záznamu v těchto dvou sekcích můžete:</p><ul><li>nechat si popis záznamu navrhnout pomocí AI z fotek,</li><li>označit místo ve výkresu – pokud stavba má výkresy a pole je v nastavení deníku zobrazené,</li><li>určit polohu v mapě ručně nebo podle polohy telefonu – pokud je pole v nastavení deníku zobrazené,</li><li>vyfotit fotku nebo natočit video,</li><li>přiložit soubor z telefonu.</li></ul><p>Jeden soubor může mít nejvýš 30 MB.</p><p>Ze záznamu v deníku můžete také založit úkol a zobrazit úkoly, které z něj vznikly – viz <a href="/buildary-help-preview/tickets/m_task_new">Nový úkol v mobilu</a>.</p><h3 id="nabidka-dalsiho-zaznamu" tabindex="-1">Nabídka Dalšího záznamu <a class="header-anchor" href="#nabidka-dalsiho-zaznamu" aria-label="Permalink to &quot;Nabídka Dalšího záznamu&quot;">​</a></h3><p>Každý Další záznam má vpravo nahoře vlastní nabídku (tři tečky). Význam voleb popisuje <a href="/buildary-help-preview/diary/dailyentriesothers">Další záznamy</a>.</p><figure class="shot" style="--w:260px;"><img src="'+l+'" alt="Nabídka Dalšího záznamu v mobilu" loading="lazy"></figure><ul><li><strong>Stažení k nahlédnutí</strong> – vytvoří PDF záznamu a otevře ho v aplikaci, kterou vyberete.</li><li><strong>Nahrej scan tohoto zápisu</strong> – nahraje naskenovaný podepsaný záznam (PDF nebo JPEG) a záznam zamkne bez elektronického podpisu.</li><li><strong>Podepsat záznam</strong> – podepíše záznam způsobem, který máte nastavený. Při podpisu v externí aplikaci jsou tu volby <strong>Stažení k elektronickému podpisu</strong> a <strong>Nahrej elektronicky podepsaný soubor</strong>.</li><li><strong>Seznam adresátů zprávy</strong> – oprávněné osoby deníku; komukoli z nich můžete o záznamu poslat e-mail.</li><li><strong>Reagovat na tento záznam</strong> – vloží odpověď navázanou na záznam.</li><li><strong>Související záznamy</strong> – ukáže celé vlákno: původní záznam a všechny reakce.</li><li><strong>Smazat</strong> – smaže záznam. U podepsaného záznamu volba není.</li></ul><div class="info custom-block"><p class="custom-block-title">Další záznamy se podepisují</p><p>Svůj Další záznam si podepisuje každý autor sám. Dokud nejsou podepsané, nejde zpravidla podepsat celý den – viz <a href="/buildary-help-preview/diary/m_signing">Podepisování v mobilu</a>.</p></div>',29)])])}const h=e(s,[["render",d]]);export{c as __pageData,h as default};
